// The renderer against the ANVL-151 Nunjucks parity corpus: 149 snippets
// rendered by Nunjucks 3.2.4 in Anvil 0.1.6's exact environment
// (test/fixtures/export/nunjucks-parity.json, regenerated by
// test/fixtures/export/tool/nunjucks_oracle.js from parity_cases.js).
//
// The unsupported set is pinned: it is the spike's, and any change to the
// renderer that adds a miss or renders different output fails here.
import 'dart:convert';

import 'package:anvil_core/anvil_core.dart';
import 'package:test/test.dart';

import 'support/fixtures.dart';
import 'support/parity.dart';

/// The cases ANVL-151 classified as unsupported: valid Nunjucks outside the
/// subset, each rejected at parse time.
const unsupportedCases = {
  'idiom.sort',
  'idiom.round_int_float',
  'idiom.sum',
  'idiom.batch_slice',
  'idiom.selectattr',
  'idiom.select_reject',
  'idiom.groupby',
  'idiom.dictsort',
  'idiom.list_filter',
  'idiom.string_filter',
  'idiom.text_filters',
  'idiom.html_filters',
  'idiom.is_tests',
  'idiom.set_block',
  'idiom.filter_block',
  'idiom.raw_block',
  'idiom.macro',
  'idiom.range',
  'idiom.cycler_joiner',
  'idiom.method_call',
};

void main() {
  final corpus = jsonDecode(
    readExportFixture('nunjucks-parity.json'),
  ) as Map<String, Object?>;
  final context = fullContext();
  final results = scoreCorpus(
    corpus,
    context,
    (source, context) => AnvilTemplate.parse(source).render(context),
  );
  String source(String name) =>
      (corpus[name] as Map<String, Object?>)['source'] as String;
  final misses = {
    for (final r in results)
      if (r.verdict != Verdict.match) r.name: r.verdict,
  };

  test('corpus size: 45 guide, 69 idiom, 32 edge, 3 host', () {
    expect(corpus.length, 149);
    int count(String group) =>
        corpus.keys.where((k) => k.startsWith('$group.')).length;
    expect(
      [count('guide'), count('idiom'), count('edge'), count('host')],
      [45, 69, 32, 3],
    );
  });

  test('every guide.* and edge.* case matches Nunjucks exactly', () {
    final bad = results
        .where((r) => r.name.startsWith('guide.') || r.name.startsWith('edge.'))
        .where((r) => r.verdict != Verdict.match);
    expect(bad.map((r) => '${r.name}: ${r.detail}'), isEmpty);
  });

  test('every unsupported case fails at parse time with kind unsupported', () {
    for (final name in unsupportedCases) {
      final check = checkTemplate(source(name));
      expect(check?.kind, TemplateErrorKind.unsupported, reason: name);
      expect(check!.line, greaterThanOrEqualTo(1), reason: name);
      expect(check.column, greaterThanOrEqualTo(1), reason: name);
      expect(
        () => AnvilTemplate.parse(source(name)),
        throwsA(
          isA<AnvilTemplateError>().having(
            (e) => e.kind,
            'kind',
            TemplateErrorKind.unsupported,
          ),
        ),
        reason: name,
      );
    }
  });

  test('the misses are exactly the pinned unsupported set, and none '
      'renders different output', () {
    printOnFailure(summarise(results));
    expect(misses.keys.toSet(), unsupportedCases);
    expect(misses.values, everyElement(Verdict.engineRejects));
    final matched = results.where((r) => r.verdict == Verdict.match).length;
    print(
      'parity corpus: $matched matched / ${misses.length} unsupported / '
      '${results.length} total',
    );
  });

  test('host.* cases (include, import, extends) are unsupported, as '
      'Nunjucks without a loader rejected them', () {
    for (final name in corpus.keys.where((k) => k.startsWith('host.'))) {
      expect(
        (corpus[name] as Map<String, Object?>)['ok'],
        isFalse,
        reason: name,
      );
      expect(
        checkTemplate(source(name))?.kind,
        TemplateErrorKind.unsupported,
        reason: name,
      );
    }
  });

  test(
    'the writing guide example is the corpus case guide.example_verbatim',
    () {
      final example = templateWritingGuide.split('```\n')[1];
      expect(example, '${source('guide.example_verbatim')}\n');
    },
  );
}
